CREATE OR REPLACE FUNCTION public.get_xp_summary(p_athlete_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_profile public.profiles%rowtype;
  v_can_view boolean := false;
  v_progress jsonb := '{}'::jsonb;
begin
  select p.*
  into v_profile
  from public.profiles p
  where p.id = p_athlete_id
    and p.role = 'athlete';

  if v_profile.id is null then
    raise exception 'Athlete not found';
  end if;

  v_can_view := auth.uid() is not null and (
    p_athlete_id = auth.uid()
    or exists (
      select 1
      from public.profiles me
      where me.id = auth.uid()
        and (
          me.role in ('coach', 'admin')
          or me.role = 'athlete'
          or (
            me.role = 'parent'
            and exists (
              select 1
              from public.parent_athletes pa
              where pa.parent_id = auth.uid()
                and pa.athlete_id = p_athlete_id
            )
          )
        )
    )
  );

  if not v_can_view then
    raise exception 'You cannot view this rider''s XP';
  end if;

  v_progress := public.sync_profile_xp(p_athlete_id);

  return v_progress || jsonb_build_object(
    'badges', public.get_level_badges(p_athlete_id),
    'current_badge', public.level_badge(coalesce((v_progress->>'level')::integer, 1))
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_assignment_progress_xp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_assignment public.weekly_trick_assignments%rowtype;
  v_row public.assignment_progress%rowtype;
  v_old_date date;
  v_new_date date;
  v_date date;
  v_venue text;
  v_source_id text;
  v_done boolean;
  v_xp integer;
  v_reason text;
begin
  v_row := coalesce(new, old);

  select wta.* into v_assignment
  from public.weekly_trick_assignments wta
  where wta.id = v_row.assignment_id;

  if v_assignment.id is null then
    return coalesce(new, old);
  end if;

  -- Daily completion XP is now issued by confirm_daily_finish only.
  if v_assignment.category = 'daily' then return coalesce(new, old); end if;

  if v_assignment.category in ('one_bang', 'dialled', 'bonus') then
    v_xp := case when v_assignment.category = 'bonus' then 250 else 35 end;
    v_reason := case when v_assignment.category = 'bonus' then 'Completed Bonus Trick' when v_assignment.category = 'dialled' then 'Landed Dialled trick' else 'Landed One Bang' end;

    perform public.sync_xp_award(
      v_assignment.athlete_id,
      v_assignment.category,
      v_assignment.id::text,
      case when tg_op <> 'DELETE' and new.completed_at is not null then v_xp else 0 end,
      v_reason,
      v_assignment.id,
      null,
      v_assignment.trick_name,
      v_assignment.venue,
      null,
      jsonb_build_object('week_start', v_assignment.week_start)
    );
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_percentage_xp_for_assignment(p_assignment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_assignment public.weekly_trick_assignments%rowtype;
  v_count integer := 0;
  v_landed integer := 0;
  v_percent integer := 0;
  v_xp integer := 0;
begin
  select wta.* into v_assignment
  from public.weekly_trick_assignments wta
  where wta.id = p_assignment_id
    and wta.category = 'percentage';

  if v_assignment.id is null then
    return '{}'::jsonb;
  end if;

  select count(*), count(*) filter (where pa.landed)
  into v_count, v_landed
  from public.percentage_attempts pa
  where pa.assignment_id = p_assignment_id;

  v_percent := case when v_count = 0 then 0 else round((v_landed::numeric / v_count::numeric) * 100)::integer end;
  v_xp := case
    when v_count < 10 then 0
    when v_percent = 100 then 75
    when v_percent >= 90 then 50
    when v_percent >= 80 then 30
    when v_percent >= 70 then 15
    else 0
  end;

  return public.sync_xp_award(
    v_assignment.athlete_id,
    'percentage',
    v_assignment.id::text,
    v_xp,
    'Percentage Trick result: ' || v_percent::text || '%',
    v_assignment.id,
    null,
    v_assignment.trick_name,
    v_assignment.venue,
    null,
    jsonb_build_object('attempts', v_count, 'landed', v_landed, 'missed', v_count - v_landed, 'percentage', v_percent)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_profile_xp(p_athlete_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total integer;
  v_level integer;
begin
  select greatest(0, coalesce(sum(xl.xp), 0))::integer
  into v_total
  from public.xp_ledger xl
  where xl.athlete_id = p_athlete_id;

  v_level := public.level_for_xp(v_total);

  update public.profiles p
  set xp_total = v_total,
      level = v_level,
      updated_at = now()
  where p.id = p_athlete_id
    and (p.xp_total is distinct from v_total or p.level is distinct from v_level);

  perform public.ensure_level_badges(p_athlete_id);

  return public.xp_progress_json(v_total);
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_xp_award(p_athlete_id uuid, p_source_type text, p_source_id text, p_xp integer, p_reason text, p_assignment_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid, p_trick_name text DEFAULT ''::text, p_venue text DEFAULT ''::text, p_coach_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before_level integer := 1; v_after_level integer := 1; v_old_xp integer := 0; v_delta integer := 0; v_progress jsonb := '{}'::jsonb;
begin
  if p_athlete_id is null or trim(coalesce(p_source_type,''))='' or trim(coalesce(p_source_id,''))='' then raise exception 'XP award is missing a rider or source'; end if;
  select coalesce(p.level,1) into v_before_level from public.profiles p where p.id = p_athlete_id;
  select coalesce(xl.xp,0) into v_old_xp from public.xp_ledger xl where xl.athlete_id=p_athlete_id and xl.source_type=p_source_type and xl.source_id=p_source_id;
  v_old_xp := coalesce(v_old_xp,0);
  if coalesce(p_xp,0)=0 then
    delete from public.xp_ledger xl where xl.athlete_id=p_athlete_id and xl.source_type=p_source_type and xl.source_id=p_source_id;
    v_delta := -v_old_xp;
  else
    insert into public.xp_ledger (athlete_id,source_type,source_id,xp,reason,assignment_id,session_id,trick_name,venue,coach_id,metadata,level_before,level_after)
    values (p_athlete_id,trim(p_source_type),trim(p_source_id),p_xp,coalesce(p_reason,''),p_assignment_id,p_session_id,coalesce(p_trick_name,''),coalesce(p_venue,''),p_coach_id,coalesce(p_metadata,'{}'::jsonb),v_before_level,v_before_level)
    on conflict (athlete_id, source_type, source_id) do update set xp=excluded.xp, reason=excluded.reason, assignment_id=excluded.assignment_id, session_id=excluded.session_id, trick_name=excluded.trick_name, venue=excluded.venue, coach_id=excluded.coach_id, metadata=excluded.metadata, updated_at=now();
    v_delta := p_xp - v_old_xp;
  end if;
  v_progress := public.sync_profile_xp(p_athlete_id);
  v_after_level := coalesce((v_progress->>'level')::integer, 1);
  update public.xp_ledger xl set level_before=v_before_level, level_after=v_after_level where xl.athlete_id=p_athlete_id and xl.source_type=p_source_type and xl.source_id=p_source_id;
  return v_progress || jsonb_build_object('athlete_id',p_athlete_id,'xp_delta',v_delta,'xp_awarded',greatest(v_delta,0),'xp_removed',greatest(-v_delta,0),'level_before',v_before_level,'level_after',v_after_level,'leveled_up',v_after_level>v_before_level,'level_badge',public.level_badge(v_after_level));
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_jkcrew_push_notifications(p_worker_secret text, p_limit integer DEFAULT 50)
 RETURNS SETOF push_notification_queue
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_expected_secret text;
begin
  select decrypted_secret into v_expected_secret from vault.decrypted_secrets where name='jkcrew_push_worker_secret' limit 1;
  if v_expected_secret is null or p_worker_secret is distinct from v_expected_secret then raise exception 'Invalid push worker secret.'; end if;
  update public.push_notification_queue q set status='skipped',processed_at=clock_timestamp(),last_error='Reminder no longer due'
    where q.status='pending' and q.notification_type='recovery_checkin_reminder'
      and not private.recovery_reminder_due(q.recipient_id,q.payload->>'episode_id',q.payload->>'checkin_date');
  return query with selected as (
    select q.id from public.push_notification_queue q where q.status='pending' and q.available_at<=now()
      and ((q.notification_type='recovery_checkin_reminder' and private.recovery_reminder_due(q.recipient_id,q.payload->>'episode_id',q.payload->>'checkin_date'))
        or (q.notification_type<>'recovery_checkin_reminder' and not private.rider_recovery_active(q.recipient_id)))
    order by q.created_at for update skip locked limit greatest(1,least(coalesce(p_limit,50),100))
  ) update public.push_notification_queue q set status='processing',attempts=q.attempts+1,processed_at=now()
    from selected where q.id=selected.id returning q.*;
end $function$
